import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';

export async function gate({ referenceDir, submissionDir }) {
  const nonce = crypto.randomBytes(32).toString('hex');
  const stamp = crypto.randomBytes(16).toString('hex');
  const runnerPath = path.join(referenceDir, 'gate-runner-' + stamp + '.mjs');
  const resultPath = path.join(referenceDir, 'gate-result-' + stamp + '.json');
  const payloadPath = path.join(referenceDir, 'gate-payload-' + stamp + '.json');
  const submissionFile = path.resolve(submissionDir, 'answer.mjs');

  const runnerSource = [
    "import fs from 'node:fs';",
    "import assert from 'node:assert/strict';",
    "import { pathToFileURL } from 'node:url';",
    "const writeFileSync = fs.writeFileSync.bind(fs);",
    "const readFileSync = fs.readFileSync.bind(fs);",
    "const unlinkSync = fs.unlinkSync.bind(fs);",
    "function finish(nonce, resultPath, accept, reason) {",
    "  writeFileSync(resultPath, JSON.stringify({ nonce: nonce, accept: accept, reason: reason, done: true }));",
    "}",
    "let nonce, resultPath, submissionFile;",
    "try {",
    "  const payload = JSON.parse(readFileSync(process.argv[2], 'utf8'));",
    "  try { unlinkSync(process.argv[2]); } catch (e) {}",
    "  nonce = payload.nonce;",
    "  resultPath = payload.resultPath;",
    "  submissionFile = payload.submissionFile;",
    "} catch (e) {",
    "  process.exit(2);",
    "}",
    "try {",
    "  const mod = await import(pathToFileURL(submissionFile).href);",
    "  const dedupeSorted = mod.dedupeSorted;",
    "  if (typeof dedupeSorted !== 'function') {",
    "    finish(nonce, resultPath, false, 'dedupeSorted is not a function');",
    "    process.exit(0);",
    "  }",
    "  const results = [];",
    "  function test(name, fn) {",
    "    try { fn(); results.push({ name: name, pass: true }); }",
    "    catch (err) { results.push({ name: name, pass: false, error: String(err && err.message ? err.message : err) }); }",
    "  }",
    "  test('empty array', () => { assert.deepStrictEqual(dedupeSorted([]), []); });",
    "  test('single element', () => { assert.deepStrictEqual(dedupeSorted([5]), [5]); });",
    "  test('no duplicates', () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); });",
    "  test('all duplicates', () => { assert.deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); });",
    "  test('duplicates at the start', () => { assert.deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); });",
    "  test('duplicates at the end', () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); });",
    "  test('negative numbers with duplicates', () => { assert.deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); });",
    "  test('randomized property check against a reference oracle', () => {",
    "    for (let trial = 0; trial < 20; trial++) {",
    "      const len = 1 + Math.floor(Math.random() * 10);",
    "      const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);",
    "      const expected = [...new Set(arr)];",
    "      assert.deepStrictEqual(dedupeSorted(arr), expected);",
    "    }",
    "  });",
    "  if (results.length !== 8) {",
    "    finish(nonce, resultPath, false, 'suite did not run to completion (' + results.length + ')');",
    "    process.exit(0);",
    "  }",
    "  const failed = results.filter((r) => !r.pass);",
    "  if (failed.length) {",
    "    finish(nonce, resultPath, false, 'failed: ' + failed.map((f) => f.name).join(', '));",
    "    process.exit(0);",
    "  }",
    "  finish(nonce, resultPath, true, 'all pinned tests passed');",
    "} catch (e) {",
    "  try { finish(nonce, resultPath, false, 'runner exception: ' + String(e && e.stack ? e.stack : e)); } catch (e2) {}",
    "  process.exit(0);",
    "}",
  ].join('\n');

  fs.writeFileSync(runnerPath, runnerSource);
  fs.writeFileSync(payloadPath, JSON.stringify({
    nonce: nonce,
    resultPath: resultPath,
    submissionFile: submissionFile
  }));

  try {
    const outcome = await new Promise((resolve) => {
      let settled = false;
      const settle = (v) => { if (!settled) { settled = true; resolve(v); } };
      const child = spawn(process.execPath, [runnerPath, payloadPath], {
        stdio: ['ignore', 'ignore', 'ignore'],
        cwd: path.resolve(submissionDir),
        env: Object.assign({}, process.env)
      });
      const timer = setTimeout(() => {
        try { child.kill('SIGKILL'); } catch (e) {}
        settle({ accept: false, reason: 'timeout waiting for test suite' });
      }, 12000);
      child.on('error', (err) => {
        clearTimeout(timer);
        settle({ accept: false, reason: 'spawn failed: ' + String(err) });
      });
      child.on('close', () => {
        clearTimeout(timer);
        try {
          const data = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
          if (data.nonce !== nonce || data.done !== true) {
            settle({ accept: false, reason: 'inauthentic or incomplete suite result' });
            return;
          }
          settle({ accept: !!data.accept, reason: String(data.reason || '') });
        } catch (e) {
          settle({ accept: false, reason: 'test suite did not complete' });
        }
      });
    });
    return outcome;
  } finally {
    try { fs.unlinkSync(runnerPath); } catch (e) {}
    try { fs.unlinkSync(resultPath); } catch (e) {}
    try { fs.unlinkSync(payloadPath); } catch (e) {}
  }
}

