    "      assert.deepStrictEqual(dedupeSorted(arr), expected);",
    "    }",
    "  });",
    "  test('deterministic long duplicate runs', () => {",
    "    const input = [];",
    "    const expected = [];",
    "    for (let v = 0; v < 15; v++) {",
    "      const run = 1 + (v % 5);",
    "      for (let i = 0; i < run; i++) input.push(v);",
    "      expected.push(v);",
    "    }",
    "    assert.deepStrictEqual(dedupeSorted(input), expected);",
    "  });",
    "  const EXPECTED = 18;",
    "  if (results.length !== EXPECTED) {",
    "    finish(nonce, resultPath, false, 'suite did not run to completion (' + results.length + ')');",
    "    process.exit(0);",
    "  }",
    "  const failed = results.filter((r) => !r.pass);",
    "  if (failed.length) {",
    "    finish(nonce, resultPath, false, 'failed: ' + failed.map((f) => f.name).join(', '));",
    "    process.exit(0);",
    "  }",
    "  finish(nonce, resultPath, true, 'all pinned tests passed');",
    "} catch (e) {",
    "  try { finish(nonce, resultPath, false, 'runner exception: ' + String(e && e.stack ? e.stack : e)); } catch (e2) {}",
    "  process.exit(0);",
    "}",
  ].join('\n');

  fs.writeFileSync(runnerPath, runnerSource);
  fs.writeFileSync(payloadPath, JSON.stringify({
    nonce: nonce,
    resultPath: resultPath,
    submissionFile: submissionFile
  }));

  try {
