      const child = spawn(process.execPath, [runnerPath, payloadPath], {
        stdio: ['ignore', 'ignore', 'ignore'],
        cwd: path.resolve(referenceDir),
        env: { NO_COLOR: '1' }
      });
      const timer = setTimeout(() => {
        try { child.kill('SIGKILL'); } catch (e) {}
        settle({ accept: false, reason: 'timeout waiting for test suite' });
      }, 12000);
      child.on('error', (err) => {
        clearTimeout(timer);
        settle({ accept: false, reason: 'spawn failed: ' + String(err) });
      });
      child.on('close', () => {
        clearTimeout(timer);
        try {
          const data = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
          if (data.nonce !== nonce || data.done !== true) {
            settle({ accept: false, reason: 'inauthentic or incomplete suite result' });
